import starlight from '@astrojs/starlight';
import { defineConfig } from 'astro/config';
import { createStarlightTypeDocPlugin } from 'starlight-typedoc';

// API reference generated by TypeDoc from the package's public entry point.
// typedoc/entries/ re-exports it under its import specifier, and
// typedoc/tsconfig.json maps @noctcore/jobs to its sources, so the site builds
// without building the package first. The output is written to
// src/content/docs/reference/api/ at build time and gitignored.
const [jobsTypeDoc, jobsApiGroup] = createStarlightTypeDocPlugin();
const typeDoc = {
  name: '@noctcore/jobs',
  excludePrivate: true,
  excludeInternal: true,
  readme: 'none',
  // Module pages named README.md are dropped by the plugin when no readme is
  // configured, while the package page still links to them; index.md is kept.
  entryFileName: 'index',
  sort: ['kind', 'alphabetical'],
  // Source links are left out: TypeDoc could not resolve repo-relative paths
  // through the entry re-export, and a bare file name helps nobody.
  disableSources: true,
};

// Project Pages for github.com/noctcore/jobs serve from
// https://noctcore.github.io/jobs/. A wrong `base` still builds green and
// 404s every asset, which is why scripts/check-build.ts reads the emitted HTML.
export default defineConfig({
  site: 'https://noctcore.github.io',
  base: '/jobs',
  trailingSlash: 'always',
  integrations: [
    starlight({
      title: '@noctcore/jobs',
      logo: {
        light: './src/assets/brand/logo-light.svg',
        dark: './src/assets/brand/logo-dark.svg',
        replacesTitle: true,
      },
      favicon: '/favicon.svg',
      customCss: [
        './src/styles/tokens.css',
        './src/styles/theme.css',
        './src/styles/landing.css',
        './src/styles/jobs.css',
      ],
      components: { Hero: './src/components/Hero.astro' },
      expressiveCode: {
        themes: ['github-dark-default', 'github-light'],
        // Long install commands wrap instead of hiding their tail behind a scrollbar.
        defaultProps: { overridesByLang: { 'sh,bash,shell': { wrap: true } } },
        styleOverrides: {
          borderRadius: 'var(--nc-radius)',
          borderColor: 'var(--nc-line-soft)',
          codeBackground: 'var(--nc-code-bg)',
          codeFontFamily: 'var(--nc-font-mono)',
          uiFontFamily: 'var(--nc-font)',
          frames: {
            editorBackground: 'var(--nc-code-bg)',
            editorTabBarBackground: 'var(--nc-bg-raised)',
            editorActiveTabBackground: 'var(--nc-code-bg)',
            editorActiveTabIndicatorTopColor: 'var(--nc-accent)',
            editorActiveTabIndicatorBottomColor: 'transparent',
            editorTabBarBorderBottomColor: 'var(--nc-line-soft)',
            terminalBackground: 'var(--nc-code-bg)',
            terminalTitlebarBackground: 'var(--nc-bg-raised)',
            terminalTitlebarBorderBottomColor: 'var(--nc-line-soft)',
            frameBoxShadowCssValue: 'none',
          },
        },
      },
      description:
        'BullMQ 6 for NestJS with the safe choice made the default: typed queues, required dedupe, bounded retries and retention, sweeps that run once per tick and a shutdown that waits for running jobs.',
      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/noctcore/jobs' }],
      plugins: [
        jobsTypeDoc({
          entryPoints: ['./typedoc/entries/jobs.ts'],
          tsconfig: './typedoc/tsconfig.json',
          output: 'reference/api',
          sidebar: { label: 'API', collapsed: true },
          typeDoc,
        }),
      ],
      editLink: { baseUrl: 'https://github.com/noctcore/jobs/edit/main/site/' },
      sidebar: [
        { label: 'Overview', link: '/' },
        {
          label: 'Start',
          items: [
            { label: 'Introduction', link: '/start/introduction/' },
            { label: 'Getting started', link: '/start/getting-started/' },
          ],
        },
        {
          label: 'Guides',
          items: [
            { label: 'Queues and policies', link: '/guides/queues-and-policies/' },
            { label: 'Dedupe', link: '/guides/dedupe/' },
            { label: 'Workers and JobHost', link: '/guides/workers/' },
            { label: 'Sweeps', link: '/guides/sweeps/' },
            { label: 'Fail-fast enqueue and connections', link: '/guides/connections/' },
            { label: 'Graceful shutdown', link: '/guides/shutdown/' },
            { label: 'Telemetry adapters', link: '/guides/telemetry/' },
            { label: 'Testing', link: '/guides/testing/' },
          ],
        },
        {
          label: 'Migrating',
          items: [
            { label: 'From raw BullMQ', link: '/migrating/bullmq/' },
            { label: 'From @nestjs/bullmq', link: '/migrating/nestjs-bullmq/' },
          ],
        },
        {
          label: 'Reference',
          items: [
            { label: 'Module options', link: '/reference/options/' },
            jobsApiGroup,
            { label: 'Changelog', link: '/reference/changelog/' },
          ],
        },
      ],
    }),
  ],
  vite: {
    // Starlight renders some Markdown through Satteri, whose native binding is an
    // optional dependency that Bun's isolated linker keeps next to `satteri` only.
    // Leave it external in Astro 7's prerender environment.
    environments: { prerender: { resolve: { external: ['satteri'] } } },
  },
});
